  Breakdown.CellCert.CellAnalysis.IsCellData α c K S B Cl R →
    ∀ (i : Fin Cl.count), ∀ n ∈ S.resolved, (∃ n' ∉ S.resolved ∪ S.band, n - n' ∈ Cl.modes i) → n ∈ Cl.resolvedPart i

∀ (L : Breakdown.Space ≃ₗᵢ[ℝ] Breakdown.Space) {m : ℕ} {v : Breakdown.Space → Breakdown.Space}
  {G : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space},
  Breakdown.SteadyCert.IsSecondOrderField m v G H →
    (∀ᵐ (y : Breakdown.Space), v (L y) = L (v y)) →
      ∀ᵐ (y : Breakdown.Space), ∀ (u u' : Breakdown.Space), ((H (L y)) (L u)) (L u') = L (((H y) u) u')

